    if path.is_file() and not overwrite:
        return f"{path} exists, left alone"
    if not apply:
        return f"would create {path}"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    return f"wrote {path}"


