def mermaid_mindmap(spec):
    lines = ["mindmap", f'  root(({spec.get("root", "Root")}))']

    def walk(node, depth):
        pad = "  " * depth
        lines.append(f"{pad}{node.get('label', '?')}")
        for c in node.get("children", []):
            walk(c, depth + 1)

    for c in spec.get("children", []):
        walk(c, 2)
    return "\n".join(lines)


